"""Real normal gallery input routes, source camera and font/cell-art presentation."""
import hashlib,json,os,unittest
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
class GalleryGraphFontControls(unittest.TestCase):
 def setUp(self):
  self.pw=sync_playwright().start();self.browser=self.pw.chromium.launch(headless=True);self.page=self.browser.new_page(viewport={'width':1440,'height':900});self.errors=[];self.page.on('pageerror',lambda e:self.errors.append(str(e)));self.page.goto(Path(os.environ.get('NOCTURNE_CONTROLS_GALLERY_PATH',ROOT/'Nocturne-Test-Harness.html')).resolve().as_uri());self.page.wait_for_function('window.nativeLab');self.page.evaluate('nativeLab.hold()')
 def tearDown(self):self.browser.close();self.pw.stop()
 def test_normal_spatial_and_flat_buttons_use_original_layout_camera_fit(self):
  p=self.page;p.select_option('#scenes','task-graph');p.evaluate('nativeLab.hold()');p.locator('#draft').fill('Graph draft e\u0301 🪶');p.locator('#draft').dispatch_event('input');before=p.evaluate('nativeLab.scene.info()');p.locator('#camera-controls-panel > summary').click();p.locator('#camera-controls-panel .camera-pose > summary').click();self.assertTrue(p.locator('#flat').is_visible());self.assertTrue(p.locator('#spatial').is_visible());p.locator('#flat').click();self.assertEqual(p.locator('#error').inner_text(),'');self.assertEqual(p.evaluate('nativeLab.scene.info().camera.yaw'),0);front=p.evaluate('nativeLab.scene.info().camera');p.locator('#spatial').click();spatial=p.evaluate('nativeLab.scene.info()')
  self.assertEqual(spatial['graph']['layoutProfile'],'source');self.assertEqual(spatial['camera']['profile'],'original');self.assertEqual(spatial['camera']['navigation'],'orbit');self.assertEqual(spatial['camera']['yaw'],-28);self.assertEqual(spatial['camera']['pitch'],-18);self.assertGreater(len({round(n['targetPosition'][2],3)for n in spatial['nodes']}),2);self.assertEqual(spatial['prompt']['text'],before['prompt']['text']);self.assertGreater(len(spatial['graph']['sourceLayout']['nodeSizes']),0);self.assertEqual(spatial['graph']['sourceLayout']['dimensions'],3);self.assertNotEqual(spatial['camera']['position'],front['position'])
  p.evaluate('nativeLab.advance(1200000)');p.locator('#flat').click();flat=p.evaluate('nativeLab.scene.info()');self.assertEqual(flat['graph']['layoutProfile'],'source');self.assertEqual(flat['camera']['yaw'],0);self.assertEqual(flat['camera']['pitch'],0);self.assertEqual({round(n['targetPosition'][2],3)for n in flat['nodes']},{0});self.assertEqual(flat['prompt']['text'],before['prompt']['text']);self.assertEqual([(n['id'],n['label'])for n in flat['nodes']],[(n['id'],n['label'])for n in spatial['nodes']]);self.assertFalse(self.errors)
 def test_actual_font_file_load_canvas_failed_load_and_reset(self):
  p=self.page;self.assertEqual(p.locator('#font-file').count(),1);p.locator('#typography').evaluate('(e)=>e.open=true');p.evaluate('window.savedNative=nativeLab.scene.snapshot()');fonts=[Path(os.environ['NOCTURNE_SHAPING_FONT'])]
  if os.environ.get('NOCTURNE_OTF_FONT'):fonts.append(Path(os.environ['NOCTURNE_OTF_FONT']))
  for font in fonts:
   raw=font.read_bytes();digest=hashlib.sha256(raw).hexdigest();p.locator('#font-file').set_input_files(str(font));p.wait_for_function('(sha)=>document.getElementById("font-status").dataset.sha256===sha',arg=digest);self.assertIn(font.name,p.locator('#font-status').inner_text());self.assertIn('OpenType',p.locator('#font-status').inner_text());canvas=p.evaluate('()=>{const c=document.getElementById("canvas"),x=c.getContext("2d");return{font:x.font,pixels:Array.from(x.getImageData(0,0,c.width,c.height).data).filter((v,i)=>i%4!==3&&v>0).length}}');self.assertIn('NocturneUploadedFont_',canvas['font']);self.assertGreater(canvas['pixels'],100)
   fontBefore=canvas['font'];p.locator('#font-file').set_input_files({'name':'invalid.otf','mimeType':'font/otf','buffer':b'not an actual font'});p.wait_for_function('document.getElementById("font-status").dataset.error==="true"');self.assertEqual(p.locator('#font-status').get_attribute('data-sha256'),digest);self.assertEqual(p.evaluate('document.getElementById("canvas").getContext("2d").font'),fontBefore)
  p.locator('#font-default').click();self.assertEqual(p.locator('#font-status').get_attribute('data-sha256'),'');self.assertNotIn('NocturneUploadedFont_',p.evaluate('document.getElementById("canvas").getContext("2d").font'));self.assertTrue(p.evaluate('()=>{const now=nativeLab.scene.snapshot();return now.length===savedNative.length&&now.every((v,i)=>v===savedNative[i])}'));self.assertFalse(self.errors)
 def test_actual_retained_tdf_cells_and_atomic_rejected_import(self):
  p=self.page;self.assertEqual(p.locator('#tdf-import').count(),1);p.locator('#typography').evaluate('(e)=>e.open=true');p.locator('#draft').fill('Keep original document');p.locator('#draft').dispatch_event('input');specimen={'width':12,'height':4,'cells':[[0x2588 if (i+i//12)%3 else 0,0xdd0000|(i*5)<<8,0x101010 if i%2 else 0] for i in range(48)]};art={'op':'cell-art','id':1,'width':specimen['width'],'height':specimen['height'],'cells':specimen['cells'],'x':3,'y':5,'layer':'overlay','alpha':1};p.locator('#tdf-import').set_input_files({'name':'cell-art.json','mimeType':'application/json','buffer':json.dumps(art).encode()});p.wait_for_function('document.getElementById("tdf-status").dataset.imported==="true"');actual=p.evaluate('(a)=>{const f=nativeLab.scene.render();return a.cells.map((_,i)=>Array.from(f.cells.slice(((a.y+Math.floor(i/a.width))*f.width+a.x+i%a.width)*4,((a.y+Math.floor(i/a.width))*f.width+a.x+i%a.width)*4+3)))}',art)
  for wanted,got in zip(art['cells'],actual):
   if wanted[0]:self.assertEqual(got,wanted)
  p.evaluate('window.savedNative=nativeLab.scene.snapshot()');p.locator('#tdf-import').set_input_files({'name':'invalid.json','mimeType':'application/json','buffer':json.dumps([art,{'op':'reset'}]).encode()});p.wait_for_function('document.getElementById("tdf-status").dataset.error==="true"');self.assertTrue(p.evaluate('()=>{const now=nativeLab.scene.snapshot();return now.length===savedNative.length&&now.every((v,i)=>v===savedNative[i])}'));self.assertEqual(p.evaluate('nativeLab.scene.info().prompt.text'),'Keep original document');self.assertFalse(self.errors)
if __name__=='__main__':unittest.main()
